/**
 * Per-endpoint revenue and rejection counters for the in-process usage() API.
 * There is no public HTTP usage endpoint.
 *
 * Deliberately in-memory and deliberately small: the issue asked for "a
 * minimal built-in usage view … no separate dashboard product". It resets on
 * restart, which is honest for what it is — an operator's sanity check that
 * money is arriving and which endpoint is earning it, not an accounting
 * record. The receipts file and the chain are the durable sources of truth.
 */
export type EndpointUsage = {
    path: string;
    /** Payments that reached settlement (or mock-mode completion). */
    payments: number;
    freeRequests: number;
    uniquePayers: number;
    /**
     * Summed atomic units across every token, as a decimal string — revenue can
     * exceed 2^53. Every offered token is a 6-decimal USD stablecoin, so the sum
     * answers "is money arriving"; `revenueByToken` answers "in what".
     */
    revenue: string;
    /** Atomic units per token symbol, e.g. `{ USDC: '20000', USAT: '10000' }`. */
    revenueByToken: Record<string, string>;
    /** Rejections by reason, e.g. `{ nonce_already_seen: 3 }`. */
    rejections: Record<string, number>;
};
export type UsageStats = {
    startedAt: string;
    totalPayments: number;
    totalFreeRequests: number;
    uniquePayers: number;
    endpoints: EndpointUsage[];
};
export type UsageRecorder = {
    recordPayment(path: string, atomicAmount: string, currency: string, payer?: string): void;
    recordFreeRequest(path: string): void;
    recordRejection(path: string, reason: string): void;
    snapshot(): UsageStats;
};
export declare function createUsageRecorder(now?: () => Date): UsageRecorder;
